function PrimaryCareProgram({lang}) {
  const isEn=lang==='en';
  const [workflow,setWorkflow]=useState('telemedicine');
  const [activeStep,setActiveStep]=useState(0);
  const [answers,setAnswers]=useState({});
  const steps=workflow==='telemedicine'?telemedicineSteps:transportationSteps;
  const score=primaryQuestions.reduce((n,q,index)=>n+(answers[index]===q.correct?1:0),0);
  const switchWorkflow=value=>{setWorkflow(value);setActiveStep(0)};
  return <div className="program-panel primary-program">
    <section className="program-intro-card"><Stethoscope/><div><span>{isEn?'THE PATIENT’S MEDICAL HOME':'EL HOGAR MÉDICO DEL PACIENTE'}</span><h3>{isEn?'General medicine connects prevention, treatment and every next step':'Medicina general conecta prevención, tratamiento y cada próximo paso'}</h3><p>{isEn?'The service does not end when an appointment is made. Staff must guide access, the licensed team provides clinical care and the organization closes every order, referral, virtual visit, ride and follow-up.':'El servicio no termina al crear una cita. El personal guía el acceso, el equipo licenciado presta la atención clínica y la organización cierra cada orden, referido, visita virtual, transportación y seguimiento.'}</p></div></section>

    <section className="primary-access"><div className="program-heading"><span>{isEn?'ACCESS RESOURCES':'RECURSOS DE ACCESO'}</span><h3>{isEn?'Services that remove barriers':'Servicios que eliminan barreras'}</h3></div><div><article><Laptop/><strong>{isEn?'Telemedicine':'Telemedicina'}</strong><p>{isEn?'CRM calendar → Practice Fusion → staff preparation → approved videoconference → clinical encounter → documented follow-up.':'Calendario CRM → Practice Fusion → preparación del personal → videoconferencia aprobada → encuentro clínico → seguimiento documentado.'}</p></article><article><CarFront/><strong>{isEn?'Transportation':'Transportación'}</strong><p>{isEn?'Appointment → driver coordination → pickup → arrival → wait/availability → return trip → documented completion.':'Cita → coordinación con chofer → recogida → llegada → espera/disponibilidad → regreso → cierre documentado.'}</p></article><article><Clock3/><strong>{isEn?'On-call 24/7':'On-call 24/7'}</strong><p>{isEn?'Use the current approved after-hours clinical channel and document the handoff. It never replaces 911 or the ER.':'Usa el canal clínico aprobado fuera de horario y documenta la transición. Nunca sustituye 911 ni ER.'}</p></article></div></section>

    <section className="primary-portfolio"><div className="program-heading"><span>{isEn?'COMPLETE MEDICAL PORTFOLIO':'PORTAFOLIO MÉDICO COMPLETO'}</span><h3>{isEn?'Open every area of primary care':'Abre cada área de medicina general'}</h3></div><div>{primaryCareAreas.map((area,index)=><details key={area.title.en}><summary><i>{String(index+1).padStart(2,'0')}</i><div><strong>{area.title[lang]}</strong><span>{area.text[lang]}</span></div></summary><ul>{area.items[lang].map(item=><li key={item}><CheckCircle2 size={15}/>{item}</li>)}</ul></details>)}</div></section>

    <section className="workflow-lab"><div className="program-heading"><span>{isEn?'INTERACTIVE OPERATIONS LAB':'LABORATORIO OPERACIONAL INTERACTIVO'}</span><h3>{isEn?'Learn every handoff, in order':'Aprende cada transición, en orden'}</h3><p>{isEn?'Choose a workflow and open every step. Skipping a step creates a failed visit or an abandoned patient.':'Elige un flujo y abre cada paso. Saltarse un paso crea una visita fallida o un paciente abandonado.'}</p></div><div className="workflow-switch"><button className={workflow==='telemedicine'?'active':''} onClick={()=>switchWorkflow('telemedicine')}><Laptop/>{isEn?'Telemedicine':'Telemedicina'}</button><button className={workflow==='transportation'?'active':''} onClick={()=>switchWorkflow('transportation')}><CarFront/>{isEn?'Transportation':'Transportación'}</button></div><div className="workflow-body"><nav>{steps.map((step,index)=><button className={activeStep===index?'active':''} key={index} onClick={()=>setActiveStep(index)}><i>{index+1}</i><span>{isEn?'Step':'Paso'} {index+1}</span><ArrowRight/></button>)}</nav><article><span>{workflow==='telemedicine'?(isEn?'TELEMEDICINE':'TELEMEDICINA'):(isEn?'TRANSPORTATION':'TRANSPORTACIÓN')} · {activeStep+1}/{steps.length}</span><h4>{steps[activeStep][lang]}</h4>{activeStep<steps.length-1?<button onClick={()=>setActiveStep(activeStep+1)}>{isEn?'Next step':'Próximo paso'}<ArrowRight/></button>:<strong><CheckCircle2/>{isEn?'Workflow reviewed':'Flujo revisado'}</strong>}</article></div></section>

    <section className="primary-knowledge"><div className="program-heading"><span>{isEn?'DECISION PRACTICE':'PRÁCTICA DE DECISIONES'}</span><h3>{isEn?'Can you operate the service?':'¿Puedes operar el servicio?'}</h3></div><div className="knowledge-score"><BookOpen/><strong>{Object.keys(answers).length}/{primaryQuestions.length} · {score} {isEn?'correct':'correctas'}</strong></div>{primaryQuestions.map((q,index)=><article key={q.q.en}><h4><i>{index+1}</i>{q.q[lang]}</h4><div>{q.answers[lang].map((answer,answerIndex)=><button className={answers[index]===answerIndex?(answerIndex===q.correct?'correct':'incorrect'):''} onClick={()=>setAnswers(current=>({...current,[index]:answerIndex}))} key={answer}><span>{String.fromCharCode(65+answerIndex)}</span>{answer}</button>)}</div>{answers[index]!==undefined&&<p>{q.why[lang]}</p>}</article>)}</section>
  </div>;
}

function ChronicCare({lang}) {
  const isEn=lang==='en';
  const [signals,setSignals]=useState(new Set());
  const [activeStep,setActiveStep]=useState(0);
  const toggle=index=>setSignals(current=>{const next=new Set(current);next.has(index)?next.delete(index):next.add(index);return next});
  return <div className="program-panel chronic-program">
    <section className="continuity-hero">
      <div><span>{isEn?'YEAR-ROUND CARE RELATIONSHIP':'RELACIÓN DE CUIDADO TODO EL AÑO'}</span><h3>{isEn?'A monthly operating system for patients with complex, ongoing needs':'Un sistema operativo mensual para pacientes con necesidades continuas y complejas'}</h3><p>{isEn?'Chronic Care keeps an eligible patient connected between office visits. The goal is not one more phone call: it is a documented cycle that anticipates gaps, coordinates the whole plan and makes the next action visible.':'Chronic Care mantiene conectado al paciente elegible entre sus visitas. No se trata de una llamada más: es un ciclo documentado que anticipa brechas, coordina el plan completo y deja visible la próxima acción.'}</p></div>
      <div className="continuity-impact"><article><HeartPulse/><strong>{isEn?'Patient value':'Valor para el paciente'}</strong><p>{isEn?'Continuity, education, earlier identification of barriers and one coordinated care plan.':'Continuidad, educación, identificación temprana de barreras y un plan coordinado.'}</p></article><article><RefreshCw/><strong>{isEn?'Company value':'Valor para la compañía'}</strong><p>{isEn?'A durable monthly relationship, stronger retention, fewer unfinished handoffs and measurable operational work—only when clinically appropriate and compliant.':'Una relación mensual duradera, mayor retención, menos transiciones incompletas y trabajo medible, solamente cuando sea clínicamente apropiado y conforme.'}</p></article></div>
    </section>

    <section className="candidate-lab">
      <div className="program-heading"><span>{isEn?'INTERACTIVE SCREENING PRACTICE':'PRÁCTICA INTERACTIVA DE IDENTIFICACIÓN'}</span><h3>{isEn?'Could this be a possible Chronic Care candidate?':'¿Podría ser candidato para Chronic Care?'}</h3><p>{isEn?'Select only the signals supported by the approved record. This exercise never establishes eligibility.':'Selecciona solamente las señales respaldadas por el expediente aprobado. Este ejercicio nunca determina elegibilidad.'}</p></div>
      <div className="signal-checklist">{chronicSignals.map((signal,index)=><button type="button" className={signals.has(index)?'selected':''} key={signal.en} onClick={()=>toggle(index)}><i>{signals.has(index)?<Check size={15}/>:index+1}</i><span>{signal[lang]}</span></button>)}</div>
      <div className={`screening-result ${signals.size===chronicSignals.length?'ready':''}`}><ShieldCheck/><div><strong>{signals.size===chronicSignals.length?(isEn?'Create a referral for specialized verification':'Crea un referido para verificación especializada'):(isEn?`${signals.size} of 4 signals documented`:`${signals.size} de 4 señales documentadas`)}</strong><p>{isEn?'The Chronic Care team—not this checklist—confirms diagnoses, duration, risk, coverage, medical necessity and enrollment.':'El equipo de Chronic Care, no este checklist, confirma diagnósticos, duración, riesgo, cobertura, necesidad médica e inscripción.'}</p></div></div>
    </section>

    <section className="enrollment-studio">
      <div className="program-heading"><span>{isEn?'FROM OPPORTUNITY TO ACTIVE PROGRAM':'DE OPORTUNIDAD A PROGRAMA ACTIVO'}</span><h3>{isEn?'Open every step of enrollment':'Abre cada paso de la inscripción'}</h3></div>
      <div className="enrollment-layout"><nav>{enrollment.map((step,index)=><button type="button" className={activeStep===index?'active':''} onClick={()=>setActiveStep(index)} key={step.title.en}><i>{index+1}</i><span>{step.title[lang]}</span><ArrowRight size={16}/></button>)}</nav><article><span>{String(activeStep+1).padStart(2,'0')} / {String(enrollment.length).padStart(2,'0')}</span><h4>{enrollment[activeStep].title[lang]}</h4><p>{enrollment[activeStep].body[lang]}</p></article></div>
    </section>

    <section className="monthly-cycle"><div className="program-heading"><span>{isEn?'REPEAT EVERY MONTH':'REPETIR CADA MES'}</span><h3>{isEn?'The operational cycle that creates continuity':'El ciclo operativo que crea continuidad'}</h3><p>{isEn?'Every month must tell a complete story: what was reviewed, what the patient reported, what the team did, what was escalated and what happens next.':'Cada mes debe contar una historia completa: qué se revisó, qué reportó el paciente, qué hizo el equipo, qué se escaló y qué ocurre después.'}</p></div><div>{monthlyCycle.map(item=><article key={item.title.en}><item.icon/><h4>{item.title[lang]}</h4><p>{item.text[lang]}</p></article>)}</div></section>

    <section className="ccm-documentation"><div className="program-heading"><span>{isEn?'THE RECORD MUST PROVE THE WORK':'EL EXPEDIENTE DEBE DEMOSTRAR EL TRABAJO'}</span><h3>{isEn?'Minimum documentation architecture':'Arquitectura mínima de documentación'}</h3></div><div className="documentation-lanes">
      <article><strong>{isEn?'Enrollment record':'Registro de inscripción'}</strong><p>{isEn?'Eligibility review, initiating visit when required, consent date/method, cost-sharing explanation, chosen provider and right to stop.':'Revisión de elegibilidad, visita inicial cuando corresponda, fecha/método del consentimiento, explicación de costos, proveedor seleccionado y derecho a retirarse.'}</p></article>
      <article><strong>{isEn?'Electronic care plan':'Plan electrónico'}</strong><p>{isEn?'Problem list, expected outcomes, measurable goals, medications, interventions, responsible clinicians, community resources, barriers and periodic review.':'Lista de problemas, resultados esperados, metas medibles, medicamentos, intervenciones, clínicos responsables, recursos comunitarios, barreras y revisión periódica.'}</p></article>
      <article><strong>{isEn?'Monthly activity':'Actividad mensual'}</strong><p>{isEn?'Outreach attempts, successful contacts, patient-reported status, coordination work, time when required, escalations, outcome and next action.':'Intentos de contacto, contactos logrados, estado reportado, coordinación, tiempo cuando corresponda, escalaciones, resultado y próxima acción.'}</p></article>
      <article><strong>{isEn?'Monitoring evidence':'Evidencia de monitoreo'}</strong><p>{isEn?'Correct office form, ordered BP/BS entries, clinician review encounter and resulting follow-up—without interpretation by non-clinical staff.':'Formulario correcto de la sede, registros BP/BS ordenados, encuentro de revisión médica y seguimiento resultante, sin interpretación por personal no clínico.'}</p></article>
    </div></section>

    <section className="role-matrix"><div className="program-heading"><span>{isEn?'CLEAR OWNERSHIP':'RESPONSABILIDAD CLARA'}</span><h3>{isEn?'Who owns each part?':'¿Quién se encarga de cada parte?'}</h3></div><div>{roles.map(role=><article key={role.title.en}><strong>{role.title[lang]}</strong><ul>{role.items[lang].map(item=><li key={item}><CheckCircle2 size={15}/>{item}</li>)}</ul></article>)}</div></section>

    <blockquote className="patient-language"><span>{isEn?'APPROVED CONVERSATION STARTER':'INICIO DE CONVERSACIÓN APROBADO'}</span>{isEn?'“Eastern Medical has a specialized program for eligible patients living with multiple ongoing conditions. The team can explain the program, verify whether it applies to you and coordinate follow-up between visits. Participation is voluntary. May I send your information securely so they can contact you?”':'“Eastern Medical tiene un programa especializado para pacientes elegibles que viven con varias condiciones continuas. El equipo puede explicarle el programa, verificar si aplica para usted y coordinar el seguimiento entre visitas. La participación es voluntaria. ¿Puedo enviar su información de forma segura para que le contacten?”'}</blockquote>
  </div>;
}

function QhsProgram({lang}) {
  const isEn=lang==='en';
  const steps=isEn?[
    ['Order confirmed','Verify patient, ordering clinician, test or BP/BS monitoring order and the correct office form.'],
    ['Patient prepared','Explain only approved instructions, cadence, dates and how to return the information. Clinical questions go to the provider.'],
    ['Information collected','Track ordered measurements or laboratory collection through the approved QHS workflow; never copy PHI to a personal spreadsheet.'],
    ['Clinician reviews','The APRN/doctor reviews the record in an encounter, interprets it and determines any clinical follow-up.'],
    ['Loop closed','Document completion, route outstanding work and communicate only the provider-approved next step to the patient.'],
  ]:[
    ['Orden confirmada','Verifica paciente, clínico que ordena, prueba o monitoreo BP/BS y el formulario correcto de la sede.'],
    ['Paciente preparado','Explica únicamente instrucciones aprobadas, frecuencia, fechas y forma de entregar la información. Las preguntas clínicas van al proveedor.'],
    ['Información recogida','Rastrea mediciones ordenadas o toma de laboratorio mediante el flujo QHS aprobado; nunca copies PHI a una hoja personal.'],
    ['Revisión médica','La APRN/doctora revisa el registro en un encuentro, lo interpreta y determina el seguimiento clínico.'],
    ['Ciclo cerrado','Documenta cumplimiento, canaliza pendientes y comunica solamente el próximo paso aprobado por el proveedor.'],
  ];
  return <div className="program-panel qhs-program"><section className="program-intro-card"><Activity/><div><span>QHS LABS + BP/BS</span><h3>{isEn?'Monitoring becomes useful only when the clinical loop closes':'El monitoreo sirve solamente cuando se cierra el ciclo clínico'}</h3><p>{isEn?'QHS supports ordered laboratory and monitoring work. Chronic Care coordinates the broader monthly care plan. They connect, but they are not the same workflow.':'QHS apoya el laboratorio y monitoreo ordenado. Chronic Care coordina el plan mensual más amplio. Se conectan, pero no son el mismo flujo.'}</p></div></section><div className="qhs-flow">{steps.map((step,index)=><React.Fragment key={step[0]}><article><i>{index+1}</i><strong>{step[0]}</strong><p>{step[1]}</p></article>{index<steps.length-1&&<ArrowRight/>}</React.Fragment>)}</div><div className="qhs-protocol"><ClipboardCheck/><div><strong>{isEn?'Current internal BP/BS protocol':'Protocolo interno actual BP/BS'}</strong><p>{isEn?'Airtable states that the physician provides the form, the office header must be checked, the patient completes it 16 times per month and then schedules physician review so the readings can be documented in an encounter. The attached form currently contains 17 entry rows, so operations must reconcile the template with the written protocol before production use.':'Airtable indica que la doctora entrega el formulario, debe revisarse el encabezado de la sede, el paciente lo completa 16 veces al mes y luego agenda revisión médica para documentar las lecturas en un encuentro. El formulario adjunto actualmente contiene 17 filas, por lo que Operaciones debe reconciliar la plantilla con el protocolo escrito antes de usarla en producción.'}</p></div></div><div className="clinical-boundary"><ShieldCheck/><p><strong>{isEn?'Never interpret a number.':'Nunca interpretes un número.'}</strong>{isEn?' Non-clinical staff collect status and route the information. The licensed clinician evaluates readings, symptoms, medications and treatment.':' El personal no clínico recopila el estado y canaliza la información. El clínico licenciado evalúa lecturas, síntomas, medicamentos y tratamiento.'}</p></div></div>;
}

function XrayProgram({lang}) {
  const isEn=lang==='en';
  const [active,setActive]=useState(0);
  const steps=isEn?[
    ['Confirm the clinical order','Verify patient identity, ordering provider, requested body area/views, diagnosis information in the approved record and whether the order is complete. Administrative staff do not decide that an X-ray is needed.'],
    ['Verify where and how it will be performed','Confirm the approved imaging location, live availability, payer network, authorization/referral requirements, appointment type and whether the patient needs transportation. Never assume every office performs every X-ray.'],
    ['Prepare and schedule the patient','Book the correct calendar, provide only approved preparation and arrival instructions and tell the patient what documents to bring. Pregnancy possibility and other clinical-safety questions must follow the imaging team’s protocol.'],
    ['Perform the study safely','Qualified imaging personnel verify the patient, order and body area, complete required safety screening, position the patient and acquire the ordered images under the approved protocol.'],
    ['Route images and report','The images go to the authorized interpreting professional. The report is returned through the approved clinical/EHR workflow to the ordering provider—not interpreted by Front Desk, Call Center or the scheduler.'],
    ['Close the follow-up loop','Track that the report was received, route it to the ordering clinician, document the status and complete the provider-approved patient communication, follow-up visit, additional study or urgent escalation.'],
  ]:[
    ['Confirmar la orden clínica','Verifica identidad, proveedor que ordena, área/vistas solicitadas, información diagnóstica del expediente aprobado y que la orden esté completa. El personal administrativo no decide que hace falta un X-ray.'],
    ['Verificar dónde y cómo se realizará','Confirma centro de imágenes aprobado, disponibilidad vigente, red del pagador, autorización/referido, tipo de cita y si necesita transportación. Nunca asumas que todas las sedes realizan todos los X-rays.'],
    ['Preparar y agendar al paciente','Agenda en el calendario correcto, entrega solo instrucciones aprobadas de preparación/llegada e indica documentos necesarios. Posible embarazo y otras preguntas de seguridad siguen el protocolo del equipo de imágenes.'],
    ['Realizar el estudio con seguridad','Personal cualificado verifica paciente, orden y área, completa el control de seguridad, posiciona al paciente y obtiene las imágenes ordenadas según protocolo.'],
    ['Canalizar imágenes e informe','Las imágenes van al profesional autorizado para interpretación. El informe regresa por el flujo clínico/EHR al proveedor que ordenó; Front Desk, Call Center y citas no lo interpretan.'],
    ['Cerrar el ciclo de seguimiento','Rastrea recepción del informe, canalízalo al clínico que ordenó, documenta estado y completa comunicación aprobada, cita, estudio adicional o escalamiento urgente indicado por el proveedor.'],
  ];
  return <div className="program-panel xray-program"><section className="program-intro-card"><ScanLine/><div><span>{isEn?'DIAGNOSTIC IMAGING WORKFLOW':'FLUJO DE IMÁGENES DIAGNÓSTICAS'}</span><h3>{isEn?'X-rays: from a complete order to a closed clinical loop':'X-rays: desde una orden completa hasta un ciclo clínico cerrado'}</h3><p>{isEn?'An X-ray service is not complete when the image is taken. The correct order, authorized location, safe study, professional interpretation, provider review and patient follow-up must all connect.':'El servicio de X-rays no termina al tomar la imagen. Deben conectarse la orden correcta, sede autorizada, estudio seguro, interpretación profesional, revisión del proveedor y seguimiento al paciente.'}</p></div></section><section className="xray-studio"><div className="program-heading"><span>{isEn?'OPEN EVERY STEP':'ABRE CADA PASO'}</span><h3>{isEn?'Operate the radiography pathway':'Opera la ruta de radiografía'}</h3></div><div><nav>{steps.map((step,index)=><button className={active===index?'active':''} onClick={()=>setActive(index)} key={step[0]}><i>{index+1}</i><span>{step[0]}</span><ArrowRight/></button>)}</nav><article><span>{isEn?'STEP':'PASO'} {active+1} / {steps.length}</span><h4>{steps[active][0]}</h4><p>{steps[active][1]}</p>{active<steps.length-1?<button onClick={()=>setActive(active+1)}>{isEn?'Continue':'Continuar'}<ArrowRight/></button>:<strong><CheckCircle2/>{isEn?'Pathway reviewed':'Ruta revisada'}</strong>}</article></div></section><div className="clinical-boundary"><ShieldCheck/><p><strong>{isEn?'Images and reports are clinical information.':'Las imágenes y los informes son información clínica.'}</strong>{isEn?' Never say an X-ray is normal, abnormal, fractured, clear or “fine.” Use: “The authorized provider will review the report and explain the findings and next step.”':' Nunca digas que un X-ray es normal, anormal, tiene fractura, está limpio o “está bien”. Usa: “El proveedor autorizado revisará el informe y explicará los hallazgos y el próximo paso”.'}</p></div></div>;
}

function AllergyProgram({lang}) {
  const isEn=lang==='en';
  return <div className="program-panel allergy-program"><section className="program-intro-card"><Stethoscope/><div><span>{isEn?'ALLERGY + IMMUNOLOGY':'ALERGIA + INMUNOLOGÍA'}</span><h3>{isEn?'A complete path from concern to specialized follow-up':'Una ruta completa desde la inquietud hasta el seguimiento especializado'}</h3><p>{isEn?'The employee identifies the request, confirms the live service and creates a warm handoff. The specialized team decides testing, candidacy, treatment and monitoring.':'El colaborador identifica la solicitud, confirma el servicio vigente y realiza una transición acompañada. El equipo especializado decide pruebas, candidatura, tratamiento y monitoreo.'}</p></div></section><div className="allergy-path">
    <article><span>01</span><h4>{isEn?'Recognize':'Reconocer'}</h4><p>{isEn?'Recurring nasal, respiratory, skin or environmental-allergy questions; request for testing; existing referral/order. Record the patient’s words without diagnosing.':'Preguntas recurrentes nasales, respiratorias, de piel o ambientales; solicitud de pruebas; orden o referido existente. Registra las palabras del paciente sin diagnosticar.'}</p></article>
    <article><span>02</span><h4>{isEn?'Verify':'Verificar'}</h4><p>{isEn?'Confirm location, clinician, schedule, payer, referral/authorization and approved preparation instructions before promising access.':'Confirma sede, clínico, agenda, pagador, referido/autorización e instrucciones aprobadas antes de prometer acceso.'}</p></article>
    <article><span>03</span><h4>{isEn?'Evaluate':'Evaluar'}</h4><p>{isEn?'The qualified professional reviews history and decides whether allergy testing, immunology evaluation or another clinical route is appropriate.':'El profesional cualificado revisa historial y decide si corresponden pruebas de alergia, evaluación inmunológica u otra ruta clínica.'}</p></article>
    <article><span>04</span><h4>{isEn?'Follow up':'Dar seguimiento'}</h4><p>{isEn?'Document attendance, ordered next step and ownership. Do not recommend medication, stop medication for testing or explain results unless authorized.':'Documenta asistencia, próximo paso ordenado y responsable. No recomiendes ni suspendas medicamentos para pruebas ni expliques resultados salvo autorización.'}</p></article>
  </div><div className="emergency-strip"><ShieldCheck/><p><strong>{isEn?'Severe reaction = emergency pathway.':'Reacción severa = ruta de emergencia.'}</strong>{isEn?' Trouble breathing, throat swelling, fainting or another suspected emergency requires 911/ER—not routine scheduling or employee triage.':' Dificultad respiratoria, inflamación de garganta, desmayo u otra emergencia sospechada requiere 911/ER, no cita rutinaria ni triaje del colaborador.'}</p></div></div>;
}

function WellnessProgram({lang}) {
  const isEn=lang==='en';
  const cards=[
    {icon:Syringe,title:{en:'Vitamin-shot service',es:'Servicio de shots de vitaminas'},purpose:{en:'Provider-directed vitamin injection options after review of the patient’s goals, history, medications, allergies and contraindications.',es:'Opciones de inyecciones de vitaminas dirigidas por proveedor después de revisar metas, historial, medicamentos, alergias y contraindicaciones.'},flow:{en:['Verify the currently offered product and benefit','Schedule clinical review and obtain required consent','Qualified staff administer and document product, lot, site and response','Give only approved aftercare and escalation instructions'],es:['Verificar producto y beneficio vigente','Agendar revisión clínica y obtener consentimiento requerido','Personal cualificado administra y documenta producto, lote, sitio y respuesta','Entregar solamente instrucciones aprobadas de cuidado y escalamiento']},boundary:{en:'Never claim that an injection prevents disease, cures fatigue or is appropriate for everyone.',es:'Nunca afirmes que una inyección previene enfermedades, cura la fatiga o es apropiada para todos.'}},
    {icon:Activity,title:{en:'Clinician-directed weight program',es:'Programa clínico para bajar de peso'},purpose:{en:'A longitudinal program that may combine assessment, nutrition, movement, measurable goals, laboratory review and medication only when clinically authorized.',es:'Programa longitudinal que puede combinar evaluación, nutrición, movimiento, metas medibles, revisión de laboratorio y medicamentos solamente cuando sean autorizados clínicamente.'},flow:{en:['Capture the person’s goal without promising a result','Schedule an individual clinical assessment','Document baseline, plan, education and follow-up cadence','Track progress, barriers, safety and clinician-directed adjustments'],es:['Recoger la meta sin prometer resultados','Agendar evaluación clínica individual','Documentar línea base, plan, educación y frecuencia de seguimiento','Rastrear progreso, barreras, seguridad y ajustes indicados']},boundary:{en:'Do not promise a number of pounds, medication eligibility, price, coverage or that the program is free.',es:'No prometas cantidad de libras, elegibilidad para medicamentos, precio, cobertura ni gratuidad.'}},
    {icon:Sparkles,title:{en:'Immune-wellness support',es:'Programa de apoyo al sistema inmunológico'},purpose:{en:'A clinician-guided wellness pathway centered on prevention, nutrition, sleep, physical activity, vaccination review and appropriate evaluation—not a promise to “boost” or guarantee immunity.',es:'Ruta de bienestar guiada clínicamente y centrada en prevención, nutrición, sueño, actividad física, revisión de vacunas y evaluación apropiada, no una promesa de “fortalecer” o garantizar inmunidad.'},flow:{en:['Understand the concern and screen for urgent symptoms','Route to the appropriate clinical evaluation','Use evidence-based education and authorized services','Set follow-up goals and document what the clinician recommends'],es:['Comprender la inquietud y detectar síntomas urgentes','Canalizar a evaluación clínica apropiada','Usar educación basada en evidencia y servicios autorizados','Establecer metas de seguimiento y documentar la recomendación clínica']},boundary:{en:'Wellness services do not replace diagnosis, vaccination, treatment or emergency care.',es:'Los servicios de bienestar no sustituyen diagnóstico, vacunación, tratamiento ni atención de emergencia.'}},
  ];
  return <div className="program-panel wellness-program"><section className="program-intro-card"><Sparkles/><div><span>{isEn?'WELLNESS WITH CLINICAL DISCIPLINE':'BIENESTAR CON DISCIPLINA CLÍNICA'}</span><h3>{isEn?'Engagement programs that create a reason to return':'Programas que crean una razón para regresar'}</h3><p>{isEn?'These services can deepen the patient relationship when the team sets honest expectations, verifies the current benefit and connects every intervention to qualified clinical oversight.':'Estos servicios fortalecen la relación con el paciente cuando el equipo establece expectativas honestas, verifica el beneficio vigente y conecta cada intervención con supervisión clínica cualificada.'}</p></div></section><div className="wellness-grid">{cards.map(card=><details key={card.title.en}><summary><card.icon/><div><strong>{card.title[lang]}</strong><span>{card.purpose[lang]}</span></div></summary><div><h4>{isEn?'Service workflow':'Flujo del servicio'}</h4><ol>{card.flow[lang].map(item=><li key={item}>{item}</li>)}</ol><p><ShieldCheck/>{card.boundary[lang]}</p></div></details>)}</div><div className="benefit-standard"><CheckCircle2/><p><strong>{isEn?'Verify “complimentary” every time.':'Verifica “complementario” cada vez.'}</strong>{isEn?' A published benefit may include a vitamin shot up to four times per year for eligible patients, but the product, eligibility, availability, clinical suitability and any cost must be confirmed live.':' Un beneficio publicado puede incluir un shot de vitaminas hasta cuatro veces al año para pacientes elegibles, pero producto, elegibilidad, disponibilidad, idoneidad clínica y costo deben confirmarse en vivo.'}</p></div></div>;
}

export default function ServicePrograms({lang='es'}) {
  const [active,setActive]=useState('primary');
  const isEn=lang==='en';
  return <section className="service-programs-studio">
    <header><span>{isEn?'DEEP-DIVE SERVICE STUDIO':'ESTUDIO PROFUNDO DE SERVICIOS'}</span><h2>{isEn?'Learn the program, operate the workflow':'Aprende el programa, opera el flujo'}</h2><p>{isEn?'Choose a service. Each experience teaches what it does, how a patient enters, who owns the work, what must be documented and where the employee’s authority ends.':'Elige un servicio. Cada experiencia enseña qué hace, cómo ingresa el paciente, quién es responsable, qué debe documentarse y dónde termina la autoridad del colaborador.'}</p></header>
    <nav aria-label={isEn?'Service learning programs':'Programas de aprendizaje de servicios'}>{programTabs.map(tab=><button type="button" className={active===tab.key?'active':''} onClick={()=>setActive(tab.key)} key={tab.key}><tab.icon size={19}/><span>{tab.label[lang]}</span></button>)}</nav>
    {active==='primary'&&<PrimaryCareProgram lang={lang}/>} {active==='chronic'&&<ChronicCare lang={lang}/>} {active==='qhs'&&<QhsProgram lang={lang}/>} {active==='xrays'&&<XrayProgram lang={lang}/>} {active==='allergy'&&<AllergyProgram lang={lang}/>} {active==='wellness'&&<WellnessProgram lang={lang}/>}
  </section>;
}
